def _member(name: str, size: int = 1, mode: int | None = None) -> Archive:
    def build(root: Path) -> Path:
        target = root / "hostile.zip"
        with zipfile.ZipFile(target, "w") as archive:
            info = zipfile.ZipInfo(name)
            if mode is not None:
                info.external_attr = mode << 16
            archive.writestr(info, "x" * size)
        return target
    return build


def _many_members(root: Path) -> Path:
    target = root / "hostile.zip"
    with zipfile.ZipFile(target, "w") as archive:
        for index in range(6):
            archive.writestr(f"f{index}.txt", "x")
    return target


def _garbage(root: Path) -> Path:
    target = root / "hostile.zip"
    target.write_bytes(b"this is not a zip archive at all")
    return target


