_LIMITS = {"MAX_MEMBER_BYTES": 32, "MAX_ZIP_ENTRIES": 5}   # small caps so the hostile archives stay tiny


def _validate(case: Case, root: Path, grammar: Path, cfg: dict) -> tuple[V.Report, str | None]:
    repo = F.emit_repo(root, grammar)
    if case.archive:
        with mock.patch.multiple(L, **_LIMITS), mock.patch.object(zipfile.ZipFile, "extractall") as extract:
            rep = V.validate_zip(case.archive(root), repo, cfg)
        return rep, ("a hostile archive was extracted" if extract.called else None)
    ret = F.emit_return(root, with_vision=case.with_vision, scope=case.scope)
    if case.mutate:
        case.mutate(repo, ret)
    return V.validate_dir(ret, repo, cfg), None


def _is_hit(case: Case, finding: V.Finding) -> bool:
    return (finding.check == case.expect and finding.severity == case.severity
            and (case.message or "") in finding.message)


def _verdict_follows_severity(case: Case, rep: V.Report) -> str | None:
    """RED versus GREEN is the product: a severity that stops moving the verdict is a disabled gate."""
    alone = all(f.check == case.expect for f in rep.findings)
    if case.severity == "WARN" and alone and rep.blocking:
        return "a WARN-only return must stay GREEN"
    if case.severity != "WARN" and not rep.blocking:
        return f"a {case.severity} finding must make the return RED"
    return None


def _verdict(case: Case, rep: V.Report) -> str | None:
    if case.forbid in {f.check for f in rep.findings}:
        return f"«{case.forbid}» fired and must not"
    if case.expect is None:
        found = [f"{f.check}: {f.message}" for f in rep.findings]
        return f"expected no finding at all, got {found}" if found else None
    if not any(_is_hit(case, f) for f in rep.findings):
        saw = sorted((f.check, f.severity) for f in rep.findings)
        return f"«{case.expect}» [{case.severity}] «{case.message or ''}» did not fire (saw {saw})"
    return _verdict_follows_severity(case, rep)


def _run_case(case: Case, grammar: Path, cfg: dict) -> str | None:
    """None when the case behaves; otherwise the reason it does not."""
    with tempfile.TemporaryDirectory(prefix="po-selftest-") as tmp:
        rep, fault = _validate(case, Path(tmp), grammar, cfg)
    return fault or _verdict(case, rep)


def _check_ids_in_source() -> tuple[set[str], set[str]]:
    """(ids passed literally as the 3rd argument of `.add`, every string constant of the module).

    Helpers receive the check id as a parameter, so a literal scan of `.add` alone would
    miss them; any declared id must at least appear somewhere as a constant."""
    tree = ast.parse(Path(V.__file__).read_text(encoding="utf-8"))
    direct: set[str] = set()
    constants: set[str] = set()
    for node in ast.walk(tree):
        if isinstance(node, ast.Constant) and isinstance(node.value, str):
            constants.add(node.value)
        is_add = isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute) and node.func.attr == "add"
        if is_add and len(node.args) >= 3 and isinstance(node.args[2], ast.Constant):
            direct.add(node.args[2].value)
    return direct, constants


def _coverage_gaps() -> list[str]:
    declared = set(V.ALL_CHECKS)
    direct, constants = _check_ids_in_source()
    covered = {c.expect for c in CASES if c.expect}
    named = {c.expect for c in CASES} | {c.forbid for c in CASES}
    gaps = [f"check «{c}» is raised but not declared in ALL_CHECKS" for c in sorted(direct - declared)]
    gaps += [f"check «{c}» is declared but nothing in the validator names it" for c in sorted(declared - constants)]
    gaps += [f"check «{c}» has no red case — a check that only sees green is decoration" for c in sorted(declared - covered)]
    gaps += [f"a case names «{c}», which is not a check id — it would pass vacuously" for c in sorted(named - declared - {None})]
    gaps += [f"case «{c.name}» expects a finding but states no severity" for c in CASES if c.expect and c.severity not in V.SEVERITIES]
    return gaps


def run(grammar: Path) -> int:
    if not grammar.exists():
        print(f"SELFTEST CANNOT RUN: the journey gate is missing at {grammar}")
        return 2
    cfg = L.merge_config(L.DEFAULT_CONFIG, F.FIXTURE_CONFIG)
    failures = 0
    for case in CASES:
        reason = _run_case(case, grammar, cfg)
        failures += 1 if reason else 0
        print(f"  {'FAIL' if reason else 'ok  '}  {case.name}" + (f" — {reason}" if reason else ""))
    for gap in _coverage_gaps():
        failures += 1
        print(f"  FAIL  coverage — {gap}")
    print(f"\nselftest: {len(CASES)} cases, {failures} failure(s)")
    return 1 if failures else 0
